responses.text:
{
  "microtasks": [
    {
      "id": 1,
      "description": "Compile and format descriptive statistics (e.g., conformity rates, frequencies) from the N=80 experimental data.",
      "prerequisites": []
    },
    {
      "id": 2,
      "description": "Perform and document the inferential statistical tests demonstrating the significance of answer changes when participants were exposed to unanimous incorrect group responses.",
      "prerequisites": [1]
    },
    {
      "id": 3,
      "description": "Draft the quantitative results section, incorporating the statistical outputs, tables, and figures representing the experimental findings.",
      "prerequisites": [2]
    },
    {
      "id": 4,
      "description": "Analyze and organize the qualitative interview data into distinct thematic categories representing different aspects of social pressure.",
      "prerequisites": []
    },
    {
      "id": 5,
      "description": "Draft the qualitative results section, describing the recurring themes of social pressure and embedding illustrative participant quotes.",
      "prerequisites": [4]
    },
    {
      "id": 6,
      "description": "Write the synthesis section that integrates the quantitative findings (the rate of conformity) with the qualitative findings (the experienced social pressure).",
      "prerequisites": [3, 5]
    },
    {
      "id": 7,
      "description": "Draft the discussion section comparing the integrated findings to established conformity literature and theoretical frameworks (e.g., normative and informational social influence).",
      "prerequisites": [6]
    },
    {
      "id": 8,
      "description": "Draft the section that explicitly addresses and answers the study's primary research questions using the integrated results.",
      "prerequisites": [6]
    },
    {
      "id": 9,
      "description": "Write the study limitations (e.g., sample size of 80, university student demographic) and suggest specific avenues for future research.",
      "prerequisites": [7, 8]
    },
    {
      "id": 10,
      "description": "Write the concluding summary for the Results and Discussion chapter.",
      "prerequisites": [9]
    },
    {
      "id": 11,
      "description": "Review and edit the entire Results and Discussion chapter for academic tone, clarity, and smooth transitions between the quantitative and qualitative sections.",
      "prerequisites": [10]
    }
  ]
}
